def read(path):return json.loads(path.read_text())
def saved(name):
    p=RAW/(name+'_repaired.json')
    return read(p if p.exists() else RAW/(name+'.json'))
def records(name):return {r['label']:r for r in saved(name)['records']}
def result(rows,label):return rows.get(label,{}).get('response',{}).get('result')
def number(rows,label,dec=18):
    s=result(rows,label)
    return int(s,16)/10**dec if s not in[None,'0x']else None
def words(s):return [int(s[i:i+64],16)for i in range(2,len(s),64)]
@functools.lru_cache(None)
def topic(sig):return '0x'+keccak(sig.encode()).hex()
def addr(word):return '0x'+word[-40:].lower()
def log_order(log):return int(log['blockNumber'],16),int(log['logIndex'],16)
def logs(name):return sorted([x for r in saved(name+'_exitlogs_T')['records']for x in r['response'].get('result',[])],key=lambda x:(int(x['blockNumber'],16),int(x['logIndex'],16)))
def utc(t):return dt.datetime.fromtimestamp(t,dt.timezone.utc).isoformat()
def waits(xs):
    if not xs:return {'observations':0,'median':None,'p90':None,'max':None}
    ys=sorted(xs);return {'observations':len(ys),'median':statistics.median(xs),'p90':ys[math.ceil(.9*len(ys))-1],'max':max(xs),'min':min(xs)}

def cash_receipts(name):
    rr=records(name+'_payout_receipts');out={};count=0
    for tx,r in rr.items():
        receipt=r['response'].get('result')
        if not receipt:continue
        if int(receipt.get('status','0x0'),16)!=1:continue
        count+=1; transfers=collections.Counter()
        for log in receipt.get('logs',[]):
            if len(log.get('topics',[]))==3 and log['topics'][0]==topic('Transfer(address,address,uint256)'):
                transfers[(log['address'].lower(),addr(log['topics'][2]),int(log['data'],16))]+=1
        out[tx]=transfers
    return out,count,len(rr)

