        if len(examples)<3 or wait>max(e['waitHours']for e in examples):
            examples.append({'requestId':x['id'],'user':x['user'],'asset':x['asset'],'paidNative':x['assetsRaw']/1e18,'requestUTC':utc(x['creation']),'paidUTC':utc(when),'waitHours':wait,'requestTransaction':x['requestTransaction'],'claimTransaction':l['transactionHash'],'tokenTransferVerified':confirmed})
            examples=sorted(examples,key=lambda e:e['waitHours'])[:2]+[max(examples,key=lambda e:e['waitHours'])]
